from pathlib import Path
import json,re,html,collections,subprocess
out=Path('artifacts/gdevelop-audit');gd=json.loads((out/'gdevelop-explicit-events.json').read_text(encoding='utf-8'));byte=json.loads(Path('artifacts/event-sheet-check/byteengine-events.json').read_text(encoding='utf-8'))
sha='f0c30988938b25f9894a849c01b4c5e6ba2ddd50'
# Curated API gaps: not a claim that corresponding low-level engine code is absent.
items=[
('Object selection sets','First','Missing event-sheet API','BaseObjectExtension','PickNearest|PickAllInstances|PickRandomInstance','Pick nearest / random / all instances, then apply actions to the selected set.','ByteEngine can target Self, a named/ID object or Last Ray Hit. Tags/existence checks do not provide GDevelop-style picked sets.'),
('Arrays and structure variables','First','Missing event-sheet API','VariablesExtension','PushVariable|PushString|RemoveVariableAt|VariableChildExists2|ClearVariableChildren','Add/remove/find entries, test child existence/count, copy structures.','ByteEngine exposes scalar/string/vector values and set/add/subtract/toggle. No collection operations are registered.'),
('Persistent values','First','Missing event-sheet API','FileExtension','EcrireFichierExp|EcrireFichierTxt|ReadNumberFromStorage|ReadStringFromStorage|FileExists','Save/load values by key, check save existence, delete a saved key.','Engine serialization exists, but no general player-save storage conditions/actions are registered.'),
('Non-blocking wait','First','Partial','TimeExtension','Wait','Wait for a duration and resume the remaining action chain.','Start/stop/finished/running timer events exist. They require a separate rule; they are not a resumable Wait action.'),
('General transform tweens','First','Partial','TweenBehavior','AddObjectPositionTween|TweenCameraPosition2|TweenSceneVariableNumber3|SceneTweenExists','Tween object/camera/value with easing; stop/pause/resume and test completion.','UI animation and skeletal transitions exist. No generic transform/value tween surface is registered.'),
('Collision lifecycle','First','Partial','Physics3DBehavior','Collision|CollisionStarted|CollisionStopped','On collision started/stopped; while colliding; identify the other body.','Raycasts, support tests and speed tests exist. These do not replace general enter/stay/exit collision events.'),
('NOT condition blocks','First','Missing event-sheet API','CommonInstructionsExtension','Not','Negate a nested group of conditions.','AND/OR exist; specific negative tests such as object.doesNotHaveTag exist. No general NOT block is available.'),
('Camera controls','First','Missing event-sheet API','CameraExtension','ZoomCamera|CenterCameraOnObject|ClampCamera|CameraZoom','Center/follow/zoom/clamp camera through events; compare zoom.','Camera components exist. Native event registry has no camera control actions/conditions.'),
('Timer pause and inspection','Next','Partial','TimeExtension','PauseTimer|UnPauseTimer|CompareTimer|TimerPaused','Pause/unpause a named timer and compare elapsed values.','ByteEngine already has start/reset, stop, finished and running timers. Pause/resume/elapsed comparisons are missing from the event surface.'),
('JSON data conversion','Next','Missing event-sheet API','CommonConversionsExtension','JSONToVariableStructure2|JSONToGlobalVariableStructure','Parse JSON into variables and serialize structured values.','Set Formatted Text exists; JSON object/array conversion is not an equivalent operation.'),
('Object relationships','Next','Partial','LinkedObjects','LinkObjects|RemoveLinkBetween|RemoveAllLinksOf|PickObjectsLinkedTo','Link/unlink gameplay objects and select linked partners without parenting.','Socket attach/detach exists. A single transform parent is not a general gameplay relationship graph.'),
('General inventory','Next','Missing event-sheet API','Inventory/Extension','Add|Remove|Has|Count|Equip|IsEquipped','Add/remove/count/equip items, limits/full checks.','The weapon plugin manages guns/ammo; a generic item inventory is not exposed.'),
('Pathfinding commands','Next','Partial','PathfindingBehavior','SetDestination|PathFound|DestinationReached','Move to destination; path found / destination reached conditions.','Enemy idle/chasing/attacking conditions exist. No general path destination or path-completion event API is registered.'),
('Dialogue and choices','Next','Missing event-sheet API','DialogueTree','StartDialogueFromBranch|GoToNextLine|ConfirmSelectOption|SelectOption','Start/advance dialogue, select choices, read dialogue state.','Text labels and button events exist; branching dialogue orchestration is missing.'),
('Named save slots','Next','Missing event-sheet API','SaveState','CreateGameSaveStateInStorage|RestoreGameSaveStateFromStorage|ListSavesInVariable|CheckedSaveExists','Save/load/list slots with asynchronous success/failure signals.','Scene serialization is an engine facility, not a registered player save/load flow.'),
('Touch events','Next','Partial','MouseExtension','HasAnyTouchStarted|PopStartedTouch|PopEndedTouch','Touch start/end and indexed multi-touch queries.','Keyboard, mouse and input-action conditions exist. Dedicated touch lifecycle/IDs are not registered.'),
('Object visibility and opacity','Next','Partial','BaseObjectExtension','Hide|Show|Visible|Opacity','Show/hide a renderer, compare visibility and animate opacity.','object.setActive disables the whole object; ui.show/hide affects UI; material color is a lower-level alternative.'),
('Audio seek and playback status','Next','Partial','AudioExtension','SoundChannelPlaying|SoundChannelPaused|SoundChannelStopped|SetSoundChannelPlayingOffset','Seek playback position, distinguish paused/stopped/finished; control audio channels.','Clip play/pause/stop, volume, pitch, looping and isPlaying already exist. Do not rebuild those.'),
('Object distance and direction','Next','Partial','BaseObjectExtension','Distance|IsMovingToward|PointInside|CollisionPoint','Compare distances and spatial relationships without extra glue.','Transforms and raycasts exist; direct distance-between-object conditions are not registered.'),
('HTTP requests','Later','Missing event-sheet API','NetworkExtension','SendAsyncRequest|SendRequest','Send a web request and continue on success/failure with response data.','No HTTP request action or response condition is registered.'),
('External URL opening','Later','Missing event-sheet API','NetworkExtension','LaunchFile','Open a web URL from an event.','game.quit exists; URL opening is a separate feature.'),
('Video controls','Later','Missing event-sheet API','Video','Play|Pause|Stop|IsPlayed|IsPaused|IsEnded','Play/pause/seek video and react to completion.','Audio and skeletal animation controls do not provide a video player event API.'),
('Reusable event-function parameters','Later','Partial','AdvancedExtension','SetReturnBoolean|SetReturnNumber|SetReturnString|CompareArgumentAsNumber','Typed parameters and return values for reusable event functions.','Event modules and plugin actions are reusable; user-authored callable event functions with explicit parameters/returns are not equivalent.'),
]
# Source-match each proposal; all published evidence is from the pinned checkout.
for item in items:
 title,priority,status,path,ids,proposal,comparison=item
 matches=[r for r in gd if path.lower() in r['file'].lower() and re.fullmatch(ids,r['id'])]
 if not matches:raise RuntimeError('No source evidence for '+title)
 item_evidence=matches
 items[items.index(item)]=dict(title=title,priority=priority,status=status,proposal=proposal,comparison=comparison,evidence=matches)
# Engine sources already cover the following -- do not present these as gaps.
covered=['Keyboard/mouse press, hold and release','Input action and axis conditions','AND / OR and Trigger Once','Timers (start/reset/stop/running/finished)','Scene load/restart and simulation time scale','Health, waves and enemy state conditions','Raycast hit object/point/normal and damage','UI text/buttons/visibility/localization','Audio playback, pitch, volume and looping','Skeletal named actions, combo queues and animation signals','Socket attachment and detachment','VFX play/stop/pause, spawning and impacts','Materials, emission, textures, metallic and roughness','Event comments/groups/colors are editor metadata, not missing gameplay actions']
meta={'sourceRepository':'https://github.com/4ian/GDevelop','sourceCommit':sha,'sourceCommitDate':'2026-10-20T16:32:01+02:00','sourceFolder':'H:/My Drive/my game engine/ui 5 source/GDevelop','explicitGDevelopDeclarations':len(gd),'byteConditions':len(byte['conditions']),'byteActions':len(byte['actions']),'reviewedGaps':len(items)}
(out/'audit-data.json').write_text(json.dumps({'metadata':meta,'gaps':items,'alreadyCovered':covered},ensure_ascii=False,indent=2),encoding='utf-8')
(out/'ByteEngine registered events.json').write_text(json.dumps(byte,indent=2),encoding='utf-8')
E=html.escape
parts=['<!doctype html><html><meta charset="utf-8"><title>ByteEngine conditions and actions audit</title><style>body{font:16px/1.6 system-ui;background:#101820;color:#e8eef2;margin:0}main{max-width:1150px;margin:auto;padding:36px}h1{font-size:32px}h2{color:#72b9ee}p,li{max-width:1000px}section{background:#19252f;border:1px solid #344958;border-radius:10px;padding:22px;margin:18px 0}a{color:#8ac8ff}small{color:#b2c3cf}.tag{color:#ffc46e}input{width:95%;padding:14px;background:#263642;color:white;border:1px solid #637986;border-radius:6px}code{word-break:break-all}summary{cursor:pointer} @media print{body{background:white;color:#111}section{background:white;border-color:#ddd;break-inside:avoid}a,h2{color:#153c59}input{display:none}}</style><main><h1>What ByteEngine is missing in event sheets</h1>']
parts+=['<p>Source-backed comparison with the latest official GDevelop checkout. This is a list to consider, not a request to implement every feature.</p>',f'<p><b>GDevelop:</b> commit <a href="https://github.com/4ian/GDevelop/commit/{sha}">{sha[:12]}</a>, 20 October 2026. <b>ByteEngine:</b> live registry with {meta["byteConditions"]} conditions and {meta["byteActions"]} actions, including Modular Weapon Gameplay.</p>',f'<p><b>Inventory:</b> {len(gd)} explicit AddAction/addAction and AddCondition/addCondition declarations from built-in C++ and JsExtension.js metadata. This count includes deprecated declarations and is not a total of all visible GDevelop operations: generated accessors, event types and community extensions need separate review.</p>','<p><b>Scope:</b> “Missing event-sheet API” means no equivalent registered action/condition was found. It does not mean the engine has no corresponding component, renderer or low-level API. “Partial” identifies an existing related system that needs more event controls.</p>','<input id="q" placeholder="Filter by feature, priority or keyword...">']
for i,item in enumerate(items,1):
 parts.append(f'<section class="item"><small class="tag">{E(item["priority"])} · {E(item["status"])}</small><h2>{i}. {E(item["title"])}</h2><p><b>Consider adding:</b> {E(item["proposal"])}</p><p><b>ByteEngine now:</b> {E(item["comparison"])}</p><details><summary>GDevelop declarations and exact source</summary><ul>')
 for r in item['evidence']:
  url=f'https://github.com/4ian/GDevelop/blob/{sha}/{r["file"]}#L{r["line"]}'
  parts.append(f'<li>{E(r["kind"])}: <b>{E(r["label"])}</b> — <code>{E(r["id"])}</code><br><a href="{url}">{E(r["file"])}:{r["line"]}</a></li>')
 parts.append('</ul></details></section>')
parts+=['<h2>Already covered — preserve and improve these</h2><ul>'+''.join('<li>'+E(x)+'</li>' for x in covered)+'</ul>','<h2>Recommended order</h2><p>Build selection sets and collection variables first. These underpin inventory, quests and reusable data systems. Then add persistent values, asynchronous waits, general tweens, collision lifecycle, NOT and camera controls. Implement these as reusable native systems/plugins with searchable, creator-friendly metadata.</p>','<h2>Further audit areas</h2><p>For Each / Repeat / While are event types, not ordinary actions. Review those separately, along with generated metadata (especially 3D physics properties), expressions, multiplayer/authentication, gamepad/community extensions, and picking semantics. This report does not mark those systems equivalent by name alone.</p>','<p>Companion files: full declaration CSV/JSON, ByteEngine registry JSON, and audit-data.json. A source declaration is evidence of an exposed API; this was not a GDevelop runtime validation or a claim of identical behavior between engines.</p></main><script>document.querySelector("#q").oninput=e=>document.querySelectorAll(".item").forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()));</script></html>']
(out/'ByteEngine conditions and actions audit.html').write_text(''.join(parts),encoding='utf-8')
